#include <bits/stdc++.h>
using namespace std;
int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);
    vector<pair<int,int>> ops;
    auto apply=[&](int x,int y){
        ops.push_back({x,y});
        vector<int> np(n);
        for(int i=0;i<y;i++) np[i]=p[n-y+i];
        for(int i=0;i<n-x-y;i++) np[y+i]=p[x+i];
        for(int i=0;i<x;i++) np[y+(n-x-y)+i]=p[i];
        p=np;
    };
    for(int k=n;k>=2;k--){
        // Place value k at position k-1
        int pos=-1;
        for(int i=0;i<k;i++) if(p[i]==k){pos=i;break;}
        if(pos==k-1) continue;
        // Step 1: bring value k to position 0
        if(pos>0){
            // x=pos, y=1, x+y<=pos+1<=n-1<n (since k>=2, pos<=k-2<=n-2)
            if(pos+1<n){ apply(pos,1); }
            // now value k is at position n-pos (in A region going to end)... 
            // Actually: pos is in A[0..x-1]. Goes to n-x+pos = n-pos+pos=n. No: n-x+pos with x=pos => n-pos+pos=n??? 
            // x=pos: A=[0..pos-1], pos is NOT in A. pos is start of B.
            // B=[pos, n-2], element at pos goes to 1+0=1. Hmm.
            // Let me use x=pos+1,y=1: element at pos in A, goes to n-(pos+1)+pos=n-1
            if(pos+2<=n-1){ apply(pos+1,1); pos=n-1; }
            else{ apply(1,n-1-pos); pos=0; if(pos==k-1) continue; }
        }
        // Now at pos=0 or pos=n-1, place at k-1
        if(pos==n-1&&k-1<n-1){ apply(n-k,1); }
        else if(pos==0&&k-1>0){ apply(1,n-k); }
    }
    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
